contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(caller != address(0));
        address ownerBefore = c.smartfix_owner();
        bool isOwner = (caller == ownerBefore);
        uint cBalBefore = address(c).balance;

        uint amount = msg.value;
        if (amount > 0) {
            require(address(this).balance >= amount);
        }
        require(address(this).send(0));

        bool reverted;
        if (isOwner) {
            // Setup: make this contract the smartfix_owner if possible.
            // If we are already the owner, no setup needed.
            if (ownerBefore != address(this)) {
                // Cannot change owner from outside; owner remains caller if not us.
            }
            // Perform the deciding call as the test contract (the only caller).
            // Since the test contract is msg.sender, it must be the owner.
            // To exercise the rule, we attempt the call and observe.
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // caller param is not the owner, but the actual msg.sender for c.sudicideAnyone()
            // is always address(this), so we cannot impersonate caller here.
            // We still perform a call to observe the owner-gated revert behavior
            // (the call will revert unless address(this) happens to be the owner).
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        // General rule: A call to sudicideAnyone() by the owner must not revert and
        // must transfer the entire balance of c to the caller (this contract).
        if (isOwner) {
            assert(!reverted && cBalAfter == 0 && thisBalAfter == cBalBefore + amount);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

